cat > /root/direct-sync/cash_probe.py <<'PY'
import sys,collections,json,time
sys.path.insert(0,"/root/unitex-finrep/engine")
import os; os.chdir("/root/unitex-finrep")
from odata_client import ODataClient
c=ODataClient()
accs={}
for a in c.list("ChartOfAccounts_Хозрасчетный", select=["Ref_Key","Code","Description"]):
    accs[(a.get("Code") or "").strip()]=(a["Ref_Key"],(a.get("Description") or "").strip())
cash={code:accs[code] for code in ("1110","1200") if code in accs}
print("грошові рахунки:",{k:v[1] for k,v in cash.items()},flush=True)
keys={v[0] for v in cash.values()}
vid={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_ВидОплаты", select=["Ref_Key","Description"])}
cur={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_Валюты", select=["Ref_Key","Description"])}
print("видів оплати:",len(vid),"валют:",len(cur),flush=True)
FLD=["Period","AccountDr_Key","AccountCr_Key","Сумма","ВалютнаяСуммаDr","ВалютнаяСуммаCr",
     "ВалютаDr_Key","ВалютаCr_Key","ВидОплаты_Key"]
flt=" or ".join("AccountDr_Key eq guid'%s' or AccountCr_Key eq guid'%s'"%(k,k) for k in keys)
t=time.time(); bal=collections.defaultdict(lambda: collections.defaultdict(float)); n=0
for r in c.list("AccountingRegister_Хозрасчетный_RecordType", select=FLD, filter=flt):
    n+=1
    v=vid.get(r.get("ВидОплаты_Key"),"(без виду оплати)")
    if r.get("AccountDr_Key") in keys:
        cu=cur.get(r.get("ВалютаDr_Key"),"?")
        bal[v][cu]+=float(r.get("ВалютнаяСуммаDr") or 0)
    if r.get("AccountCr_Key") in keys:
        cu=cur.get(r.get("ВалютаCr_Key") or r.get("ВалютаDr_Key"),"?")
        bal[v][cu]-=float(r.get("ВалютнаяСуммаCr") or 0)
    if n%20000==0: print("  ...",n,"записів, %.0fс"%(time.time()-t),flush=True)
print("ВСЬОГО РУХІВ по грошових рахунках: %d за %.0fс"%(n,time.time()-t),flush=True)
print("\nЗАЛИШКИ ПО ВИДАХ ОПЛАТИ (з бухрегістру):")
for v in sorted(bal):
    parts=", ".join("%s %.2f"%(cu,s) for cu,s in sorted(bal[v].items()) if abs(s)>0.005)
    if parts: print("   %-34s %s"%(v[:34],parts))
json.dump({v:dict(d) for v,d in bal.items()},open("/root/direct-sync/cash_from_register.json","w"),ensure_ascii=False,indent=1)
PY
cd /root/direct-sync && nohup /root/unitex-finrep/.venv/bin/python cash_probe.py > /root/direct-sync/cash_probe.out 2>&1 &
sleep 95; tail -20 /root/direct-sync/cash_probe.out
